head.b:skin:
/*
-----------------------------------------------
The Workbench
Custom Blogger theme (layouts v3, widgets v2)
Dark-first, Maximum Global Business house palette
-----------------------------------------------
<Group description="Colors">
  <Variable name="keycolor" description="Accent" type="color" default="#1AA0E6" value="#1AA0E6"/>
  <Variable name="body.background.color" description="Background" type="color" default="#10233F" value="#10233F"/>
</Group>
*/

/* ---------- design tokens ---------- */
:root {
  /* dark (default): MGB navy family */
  --bg: #0C1B33;
  --bg-raised: #10233F;
  --card: #1B3557;
  --card-border: #274672;
  --text: #E8EEF6;
  --text-soft: #B9C7DA;
  --muted: #8FA3BC;
  --accent: #1AA0E6;
  --accent-soft: #BFE3F7;
  --code-bg: #0A1628;
  --code-border: #223D63;
  --chip-bg: rgba(26, 160, 230, 0.14);
  --shadow: 0 10px 30px rgba(2, 8, 20, 0.45);
  --legacy-body-bg: #FFFFFF;
  --legacy-body-text: #1F2937;
}
[data-theme="light"] {
  --bg: #FFFFFF;
  --bg-raised: #F8FBFD;
  --card: #F2F8FC;
  --card-border: #D7E7F2;
  --text: #10233F;
  --text-soft: #334155;
  --muted: #64748B;
  --accent: #0F84C2;
  --accent-soft: #1AA0E6;
  --code-bg: #0C1B33;
  --code-border: #223D63;
  --chip-bg: rgba(26, 160, 230, 0.12);
  --shadow: 0 8px 24px rgba(16, 35, 63, 0.10);
  --legacy-body-bg: transparent;
  --legacy-body-text: inherit;
}

/* ---------- reset / base ---------- */
* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: 'Inter', -apple-system, 'Segoe UI', sans-serif;
  font-size: 17px;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
  transition: background-color .25s ease, color .25s ease;
}
a { color: var(--accent); text-decoration: none; }
a:hover { text-decoration: underline; text-underline-offset: 3px; }
img { max-width: 100%; height: auto; }

.wrap { max-width: 1080px; margin: 0 auto; padding: 0 24px; }
.wrap-narrow { max-width: 780px; margin: 0 auto; padding: 0 24px; }

/* ---------- masthead ---------- */
.topbar {
  background: var(--bg-raised);
  border-bottom: 1px solid var(--card-border);
  position: sticky;
  top: 0;
  z-index: 50;
  backdrop-filter: blur(8px);
}
.topbar-inner {
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 14px 0;
}
.brand { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.site-title {
  font-weight: 800;
  font-size: 1.35rem;
  letter-spacing: -0.02em;
  color: var(--text);
  white-space: nowrap;
}
.site-title:hover { text-decoration: none; color: var(--accent); }
.site-title .tick { color: var(--accent); }
.byline {
  margin: 0;
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.72rem;
  color: var(--muted);
  letter-spacing: 0.02em;
  white-space: nowrap;
}
.topbar-spacer { flex: 1; }
.site-nav { display: flex; gap: 4px; flex-wrap: wrap; }
.site-nav a {
  color: var(--text-soft);
  font-size: 0.92rem;
  font-weight: 500;
  padding: 7px 12px;
  border-radius: 8px;
}
.site-nav a:hover { color: var(--text); background: var(--card); text-decoration: none; }
.site-nav a.active { color: var(--accent); background: var(--chip-bg); }

.topbar-tools { display: flex; align-items: center; gap: 8px; }
.search-form { display: flex; align-items: center; }
.search-form input {
  background: var(--card);
  border: 1px solid var(--card-border);
  color: var(--text);
  border-radius: 8px;
  padding: 7px 12px;
  font: inherit;
  font-size: 0.88rem;
  width: 150px;
  transition: width .2s ease, border-color .2s ease;
}
.search-form input:focus { outline: none; border-color: var(--accent); width: 200px; }
.search-form input::placeholder { color: var(--muted); }
.theme-toggle {
  background: var(--card);
  border: 1px solid var(--card-border);
  color: var(--text);
  border-radius: 8px;
  width: 36px;
  height: 36px;
  cursor: pointer;
  font-size: 1rem;
  line-height: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.theme-toggle:hover { border-color: var(--accent); }

/* ---------- hero (homepage only) ---------- */
.hero { padding: 56px 0 8px; }
.hero .kicker {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--accent);
  margin: 0 0 10px;
}
.hero h1 {
  margin: 0 0 10px;
  font-size: clamp(1.7rem, 4vw, 2.5rem);
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 1.15;
}
.hero p { margin: 0; color: var(--muted); max-width: 640px; }

/* ---------- listing / section heading ---------- */
.listing-head { padding: 40px 0 4px; }
.listing-head h1 {
  margin: 0;
  font-size: 1.4rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}
.listing-head .count { color: var(--muted); font-weight: 400; }

/* ---------- post cards ---------- */
.post-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 22px;
  padding: 32px 0 16px;
}
.card {
  background: var(--card);
  border: 1px solid var(--card-border);
  border-radius: 14px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform .18s ease, box-shadow .18s ease, border-color .18s ease;
}
.card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow);
  border-color: var(--accent);
}
.card-thumb { display: block; aspect-ratio: 16/9; overflow: hidden; background: var(--bg); }
.card-thumb img { width: 100%; height: 100%; object-fit: cover; display: block; }
.card-body { padding: 18px 20px 20px; display: flex; flex-direction: column; gap: 10px; flex: 1; }
.card-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.72rem;
  color: var(--muted);
}
.card h2 { margin: 0; font-size: 1.08rem; line-height: 1.4; letter-spacing: -0.01em; }
.card h2 a { color: var(--text); }
.card h2 a:hover { color: var(--accent); text-decoration: none; }
.card .snippet { margin: 0; font-size: 0.9rem; color: var(--muted); flex: 1; }
.card .read-more {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--accent);
}

.chip {
  display: inline-block;
  background: var(--chip-bg);
  color: var(--accent-soft);
  border-radius: 999px;
  padding: 2px 10px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.68rem;
  letter-spacing: 0.04em;
}
[data-theme="light"] .chip { color: var(--accent); }
.chip.archive { background: rgba(148, 163, 184, 0.16); color: var(--muted); }

/* ---------- pagination ---------- */
.pager { display: flex; justify-content: space-between; gap: 16px; padding: 24px 0 56px; }
.pager a {
  background: var(--card);
  border: 1px solid var(--card-border);
  color: var(--text);
  padding: 10px 18px;
  border-radius: 10px;
  font-size: 0.9rem;
  font-weight: 600;
}
.pager a:hover { border-color: var(--accent); text-decoration: none; color: var(--accent); }
.pager .spacer { flex: 1; }

/* ---------- single post / page ---------- */
.post { padding: 48px 0 24px; }
.post-head { margin-bottom: 28px; }
.post-head .card-meta { margin-bottom: 14px; }
.post-title {
  margin: 0 0 6px;
  font-size: clamp(1.6rem, 4vw, 2.3rem);
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 1.2;
}
.archive-note {
  display: none;
  background: var(--chip-bg);
  border: 1px solid var(--card-border);
  border-left: 3px solid var(--accent);
  border-radius: 10px;
  padding: 12px 16px;
  font-size: 0.88rem;
  color: var(--text-soft);
  margin: 0 0 24px;
}
.archive-note.show { display: block; }

.post-body { font-family: 'Newsreader', Georgia, 'Times New Roman', serif; font-size: 1.16rem; line-height: 1.75; }
.post-body p { margin: 0 0 1.2em; }
.post-body h2, .post-body h3, .post-body h4 {
  letter-spacing: -0.01em;
  line-height: 1.3;
  margin: 1.8em 0 0.6em;
}
.post-body blockquote {
  margin: 1.4em 0;
  padding: 4px 20px;
  border-left: 3px solid var(--accent);
  background: var(--card);
  border-radius: 0 10px 10px 0;
  color: var(--text-soft);
}
.post-body pre, .post-body code {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.88em;
}
.post-body pre {
  background: var(--code-bg);
  border: 1px solid var(--code-border);
  color: #DCE7F5;
  border-radius: 10px;
  padding: 16px 18px;
  overflow-x: auto;
  line-height: 1.6;
}
.post-body :not(pre) > code {
  background: var(--card);
  border: 1px solid var(--card-border);
  border-radius: 5px;
  padding: 1px 6px;
}
.post-body table {
  border-collapse: collapse;
  width: 100%;
  margin: 1.4em 0;
  font-size: 0.92em;
  display: block;
  overflow-x: auto;
}
.post-body th, .post-body td {
  border: 1px solid var(--card-border);
  padding: 8px 12px;
  text-align: left;
}
.post-body th { background: var(--card); }
.post-body img { border-radius: 10px; }

/* legacy (pre-rebrand) posts carry old inline colors that assume a white
   page, so their body renders on a light panel even in dark mode */
.post-body.legacy {
  background: var(--legacy-body-bg);
  color: var(--legacy-body-text);
  border-radius: 12px;
}
[data-theme]:not([data-theme="light"]) .post-body.legacy,
html:not([data-theme]) .post-body.legacy { padding: 24px 28px; }
.post-body.legacy a { color: #0F84C2; }

.post-labels { display: flex; gap: 8px; flex-wrap: wrap; padding: 20px 0 0; }

/* ---------- comments ---------- */
.comments-shell { padding: 8px 0 48px; }
.comments-shell h3 {
  font-size: 1.05rem;
  letter-spacing: -0.01em;
  border-top: 1px solid var(--card-border);
  padding-top: 28px;
}
.comments-shell iframe { background: #fff; border-radius: 10px; }

/* ---------- footer ---------- */
.site-footer {
  background: var(--bg-raised);
  border-top: 1px solid var(--card-border);
  margin-top: 40px;
  padding: 36px 0;
  font-size: 0.88rem;
  color: var(--muted);
}
.site-footer .wrap {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  align-items: center;
}
.site-footer a { color: var(--text-soft); }
.site-footer a:hover { color: var(--accent); }
.footer-heritage { font-family: 'JetBrains Mono', monospace; font-size: 0.75rem; }

/* ---------- status / empty ---------- */
.status-msg { padding: 48px 0; color: var(--muted); }

/* ---------- responsive ---------- */
@media (max-width: 760px) {
  .topbar-inner { flex-wrap: wrap; gap: 10px; }
  .brand { flex-basis: 100%; }
  .byline { white-space: normal; }
  .search-form input, .search-form input:focus { width: 130px; }
  .hero { padding-top: 36px; }
  .post { padding-top: 32px; }
}

/* Blogger injects a few of its own bits; keep them tidy */
.blogger-clickTrap, #b-navbar { display: none !important; }
.post-body pre code.hljs { background: transparent; padding: 0; }

body.script:
//
(function () {
  // ----- light / dark toggle (dark is the default) -----
  var KEY = 'wb-theme';
  var root = document.documentElement;
  var btn = document.getElementById('themeToggle');
  function apply(mode) {
    if (mode === 'light') { root.setAttribute('data-theme', 'light'); }
    else { root.removeAttribute('data-theme'); }
    if (btn) { btn.innerHTML = (mode === 'light') ? '☾' : '☀'; }
  }
  var saved = null;
  try { saved = localStorage.getItem(KEY); } catch (e) {}
  apply(saved === 'light' ? 'light' : 'dark');
  if (btn) {
    btn.addEventListener('click', function () {
      var next = root.hasAttribute('data-theme') ? 'dark' : 'light';
      apply(next);
      try { localStorage.setItem(KEY, next); } catch (e) {}
    });
  }

  // ----- archive-era detection (anything before the rebrand cutoff) -----
  var CUTOFF = new Date('2025-01-01T00:00:00Z');
  document.querySelectorAll('time[data-ts]').forEach(function (t) {
    var d = new Date(t.getAttribute('data-ts'));
    if (isNaN(d) || d >= CUTOFF) { return; }
    var meta = t.closest('.card-meta');
    if (meta && !meta.querySelector('.chip.archive')) {
      var chip = document.createElement('span');
      chip.className = 'chip archive';
      chip.textContent = 'archive';
      meta.appendChild(chip);
    }
    // single-post view: show the notice and render the body on a light panel
    var body = document.getElementById('postBody');
    var note = document.getElementById('archiveNote');
    if (body && t.closest('.post-head')) {
      body.classList.add('legacy');
      if (note) { note.classList.add('show'); }
    }
  });
})();
//
